visual.source:
flowchart TB
  LG@{ svc: "Amazon CloudWatch Logs", label: "log group" }
  SF["subscription filter<br/>gzip で圧縮して送る"]
  KD@{ svc: "Amazon Kinesis Data Streams", label: "Kinesis Data Streams" }
  LA@{ svc: "AWS Lambda", label: "Lambda<br/>base64 で届く" }
  FH@{ svc: "Amazon Data Firehose", label: "Data Firehose" }
  OS["Amazon OpenSearch<br/>Service<br/>Standard の<br/>log group だけ"]
  LG -- "ログ" --> SF
  SF --> KD
  SF --> LA
  SF --> FH
  SF --> OS

flowchart TB
  CW@{ svc: "Amazon CloudWatch", label: "CloudWatch の<br/>メトリクス<br/>全部か filter で一部" }
  MS["metric streams<br/>ほぼリアルタイム"]
  FH@{ svc: "Amazon Data Firehose", label: "Data Firehose<br/>望む先へ届ける" }
  S3@{ svc: "Amazon S3", label: "Amazon S3<br/>quick setup" }
  CW --> MS
  MS -- "delivery stream" --> FH
  MS --> S3

flowchart TB
  subgraph SS["保存時の server-side 暗号化"]
    AES["default<br/>AES-GCM 256 ビット"]
    KEY@{ svc: "AWS KMS", label: "代わりに<br/>AWS KMS の key<br/>log group ごとに<br/>別の key（勧め）" }
  end
  LG@{ svc: "Amazon CloudWatch Logs", label: "log group<br/>関連付け後に入るデータ" }
  P@{ svc: "AWS IAM", label: "呼び出す側<br/>IAM principal<br/>kms:DescribeKey が要る" }
  KEY -- "暗号化" --> LG
  P -- "CreateLogGroup か AssociateKmsKey" --> LG
